def same_color_adjacent_pairs(grid, queries):
    """
    Returns a list of integers representing the number of same-color adjacent pairs for each query.

    Args:
    grid (list[list[int]]): A 2D grid of pixels where each pixel has a color.
    queries (list[tuple[int, int, int, int]]): A list of queries, where each query is a tuple of four integers (x1, y1, x2, y2).

    Returns:
    list[int]: A list of integers representing the number of same-color adjacent pairs for each query.
    """

    def get_color_count(grid):
        color_count = {}
        for row in grid:
            for pixel in row:
                if pixel not in color_count:
                    color_count[pixel] = 0
                color_count[pixel] += 1
        return color_count

