def prime_pairs_sum_to_n(n):
    """Find all pairs of prime numbers within [2, n] that sum up to n, sorted by the first number in each pair."""
    primes = [i for i in range(2, n + 1) if is_prime(i)]
    pairs = [(p1, p2) for p1 in primes for p2 in primes if p1 + p2 == n and p1!= p2]
